    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(anchors) < 2:
        return grid

    def nearby(r, c):
        return sum(
            grid[rr][cc] != 0 and grid[rr][cc] != 5
            for rr in range(max(0, r - 3), min(h, r + 4))
            for cc in range(max(0, c - 3), min(w, c + 4))
        )

    src = max(anchors, key=lambda p: nearby(*p))
    dst = min((p for p in anchors if p != src), key=lambda p: nearby(*p))
    dr, dc = dst[0] - src[0], dst[1] - src[1]
    out = [row[:] for row in grid]
    out[dst[0]][dst[1]] = 0

    # Move the colored pattern around one marker to the other marker,
    # omitting both marker cells themselves.
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value == 0 or value == 5:
                continue
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
